"""Generate findings directly from validated data and computed chart results."""
from __future__ import annotations

from pathlib import Path
import pandas as pd

from .data import Dataset
from .plotting import Chart


def markdown_table(df: pd.DataFrame) -> str:
    """Small Markdown table without requiring an optional formatting dependency."""
    def fmt(v: object) -> str:
        if isinstance(v, bool):
            return str(v)
        if isinstance(v, float):
            return f"{v:,.2f}"
        if isinstance(v, int):
            return f"{v:,}"
        return str(v)
    rows = ["| " + " | ".join(map(str, df.columns)) + " |",
            "| " + " | ".join("---" for _ in df.columns) + " |"]
    rows += ["| " + " | ".join(fmt(v) for v in row) + " |" for row in df.itertuples(index=False, name=None)]
    return "\n".join(rows)


def write_reports(root: Path, data: Dataset, tables: dict[str, pd.DataFrame], charts: list[Chart]) -> None:
    r, t = data.repositories, data.tools
    text = ["# SpecMine SDD analysis findings", "",
        "Generated by `python -m src.pipeline` from the unchanged cleaned CSVs. All findings describe this sample and first detected specification commits, a proxy for adoption. They do not establish causation or GitHub-wide prevalence.",
        "", "## Data and validation", "",
        f"The sample has **{len(r):,} distinct repositories** and **{len(t):,} repository-category pairs**, with {t.spec_tool.nunique()} category labels. Repository keys and pair keys are unique. Metadata, category counts, specification totals, first dates, status flags and timestamp chronology pass validation. DATA_COLUMNS.md was read completely and its column definitions and age-filter rules were used.",
        "", "### Age inclusion/exclusion", "", markdown_table(tables["age_status_audit"]),
        "", "Only status `valid` enters the corresponding age analysis. These cohorts are filtered independently; neither filter changes the full-sample repository or category data. Group age tables report all numeric summaries and per-status counts.",
        "", "### Numeric summaries", "", markdown_table(tables["numeric_summary"]), "",
        "Counts refer to the grain named in each row. No tail observations are dropped from these statistics; years are supplied conversions and days are the main analysis unit."]
    for rq, title in (("rq1", "RQ1: What types of repositories use detected SDD?"),
                      ("rq2", "RQ2: At what age is SDD first detected?"),
                      ("rq3", "RQ3: How do detections and category use change over time?")):
        text += ["", "## " + title, ""]
        for chart in charts:
            if chart.name.startswith(rq):
                text += [f"- [{chart.name}](figures/{chart.name}.png): {chart.interpretation}"]
    text += ["", "## Limitations and interpretation", "",
        "- **Sampling and detection:** This is a sample of repositories with detected SDD specifications, with no comparison population or GitHub-wide denominator. Repository inclusion, crawling and detection may vary by time, language and category. Trends are counts of first detections, not active use, true adoption rates, retention, or causal effects.",
        f"- **Time coverage:** Detected dates run from {r.first_sdd_at.min():%Y-%m-%d} to {r.first_sdd_at.max():%Y-%m-%d}. The dataset ends in July 2026. July and 2026 are partial and are not annualized. The latest detected commit is not a verified extraction timestamp; completeness even within earlier calendar periods cannot be assumed.",
        "- **Predating histories:** Imported or migrated commit histories can predate repository creation. Their cause is not established by these tables. They remain in non-age summaries and dated trends, but not age calculations. `results/monthly_repository_counts_by_age_status.csv` supports a sensitivity comparison.",
        f"- **Missingness:** {r.repo_language.isna().sum():,} repositories lack a main language; they are shown separately in the language figure. {r.first_sdd_at.isna().sum():,} repositories and {t.first_tool_adoption_at.isna().sum():,} category pairs lack first-detection dates and cannot contribute to trends. All other appropriate analyses retain them.",
        "- **Fork distinction:** repo_fork is uniformly False/0, so no fork-vs-non-fork comparison is possible. repo_forks measures the number of forks received and is analyzed separately.",
        "- **Category semantics:** root_bare, docs_embedded and other generic or location labels are detection categories, not named software products. All labels are shown as dataset categories; product identities are not inferred. Category memberships overlap and category counts must not be summed into unique repository counts.",
        "- **Measurement:** Main language is one GitHub label rather than a full language inventory. Stars and forks are snapshot counts. Specification counts cover detected files, and logged-in specification contributors count unique GitHub accounts committing to those files, not all contributors or people. Zero logged-in contributors does not imply no human activity.",
        "- **Conditional ages:** Age results exclude invalid chronology and missing dates; groups may differ in exclusion rates. Rounded zero-day values can include very early adoption. Group median/IQR comparisons are descriptive, and IQRs are not confidence intervals. Multiple category rows from one repository are not independent observations.",
        "", "## Suggestions for the final report", "",
        "1. Lead with the sample design and the distinct repository/category grains. Use the repository profile, valid-age distribution, and monthly first-detection figures as the main RQ evidence.",
        "2. Report medians and IQRs with valid cohort sizes and excluded status counts; include means and maxima to document skew. Explain log1p axes, which retain zero and the full tail.",
        "3. Compare 2024 and 2025 as observed calendar-year sample counts; discuss 2026 only as an incomplete interval. Avoid interpreting the final partial-month fall as a decline. For follow-up, compare equal observed intervals only after coverage is verified.",
        "4. Use the status-separated monthly table and group exclusion counts to assess sensitivity to predating histories and selection into the valid-age cohort. Investigate history migration with additional evidence before attributing a cause.",
        "5. For broader claims, obtain a documented sampling frame, collection cutoff, comparable non-SDD repositories, and detection precision/recall estimates. Do not infer causal effects of SDD on popularity or collaboration."]
    (root / "ANALYSIS_FINDINGS.md").write_text("\n".join(text) + "\n", encoding="utf-8")
    guide = ["# Data validation and analysis contract", "",
        "DATA_COLUMNS.md was read in full after it was added to the checkout. The validation implements its definitions without modifying or re-cleaning either input CSV.", "",
        "- Repository grain: unique repo_name. Category grain: unique (repo_name, spec_tool). Both tables cover the same repository set.",
        "- Required columns, nonnegative integer counts, boolean encodings, UTC timestamps and adoption_year/date consistency are checked.",
        "- Clean days/years must be present and nonnegative exactly for valid statuses, absent otherwise. Validity flags and statuses must agree with full timestamp chronology; rounded raw -0.0 cannot override status. Clean/raw days must agree with timestamps within rounding tolerance.",
        "- Cross-table metadata, category lists/counts, specification sums, and minimum category dates agree with repository records.",
        "- Repository-age filter: adoption_age_status == 'valid'. Category-age filter: tool_adoption_age_status == 'valid'. Non-age plots retain all statuses. Trends exclude missing first-detection dates only.",
        "- sdd_tools is observed as a comma-separated category list. spec_tool is a category identifier, including generic and location categories. No product classification is invented.",
        "- repo_fork is constant False; repo_forks is a numeric popularity measure. Contributors count unique GitHub accounts committing to detected specification files.",
        "- Results use days for ages. Supplied years are checked within rounding tolerance; the dictionary does not specify the day-to-year divisor.",
        "", "## Input fingerprints", ""]
    guide += [f"- `{name}`: `{digest}`" for name, digest in data.audit["input_sha256"].items()]
    guide += ["", "Machine-readable counts, missingness, date ranges and versions are in results/validation_report.json."]
    (root / "DATA_VALIDATION.md").write_text("\n".join(guide) + "\n", encoding="utf-8")
